    token = sequence.nextToken();
    // After suppressing, the token should be returned from the delegate
    Assert.assertThat(token, is(JsonToken.START_OBJECT));
    // And the suppress flag should be reset to false
    Assert.assertFalse("suppress flag should be false after use", sequence._suppressNextToken);
